        if ($form==='delete_record') { $id=(int)($_POST['id']??0); db()->prepare('UPDATE records SET deleted_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=? AND deleted_at IS NULL')->execute([$id,$_SESSION['user_id']]); flash('Uitgave verplaatst naar de prullenbak.'); redirect('?page=trash'); }
        if ($form==='update_compilation') { $id=(int)($_POST['id']??0); db()->prepare('UPDATE records SET is_compilation=? WHERE id=? AND user_id=? AND deleted_at IS NULL')->execute([isset($_POST['is_compilation'])?1:0,$id,$_SESSION['user_id']]); flash('Verzamelalbum-label bijgewerkt.'); redirect('?page=record&id='.$id); }
        if ($form==='refresh_record') { $id=(int)($_POST['id']??0);$s=db()->prepare('SELECT barcode FROM records WHERE id=? AND user_id=? AND deleted_at IS NULL');$s->execute([$id,$_SESSION['user_id']]);$record=$s->fetch();if(!$record||empty($record['barcode']))throw new RuntimeException('Dit album heeft geen barcode om MusicBrainz te raadplegen.');$release=musicRelease($record['barcode']);db()->prepare('UPDATE records SET artist=?,title=?,format=?,tracklist=?,track_artists=?,release_year=?,duration_seconds=?,is_compilation=?,musicbrainz_release_group=? WHERE id=? AND user_id=? AND deleted_at IS NULL')->execute([$release['artist'],$release['title'],$release['format'],$release['tracklist'],$release['track_artists'],$release['year'],$release['duration_seconds'],$release['is_compilation']?1:0,$release['release_group'],$id,$_SESSION['user_id']]);flash('Albumgegevens opnieuw opgehaald uit MusicBrainz.');redirect('?page=record&id='.$id); }
        if ($form==='empty_trash') { $items=db()->prepare('SELECT cover_path,cover_thumb_path,back_path,barcode_path FROM records WHERE user_id=? AND deleted_at IS NOT NULL');$items->execute([$_SESSION['user_id']]);foreach($items as $item)foreach(['cover_path','cover_thumb_path','back_path','barcode_path'] as $field)if(!empty($item[$field])&&is_file(UPLOADS.'/'.$item[$field]))unlink(UPLOADS.'/'.$item[$field]);db()->prepare('DELETE FROM records WHERE user_id=? AND deleted_at IS NOT NULL')->execute([$_SESSION['user_id']]);flash('Prullenbak geleegd.');redirect('?page=trash'); }
        if ($form==='openai_settings') { if (($_POST['mode']??'')==='remove') VisionBarcode::removeKey(); else VisionBarcode::saveKey($_POST['openai_api_key']??''); flash('OpenAI-integratie bijgewerkt.'); redirect('?page=integrations'); }
        if ($form==='apply_update') { if (empty($_SERVER['HTTPS']) || $_SERVER['HTTPS']==='off') throw new RuntimeException('Updates zijn uitsluitend via HTTPS toegestaan.'); $message=Updater::install(ROOT, STORE); flash($message); redirect('?page=updates'); }
        if ($form==='record') { $artist=trim($_POST['artist']??'');$title=trim($_POST['title']??'');$format=$_POST['format']??'';$compilation=isset($_POST['is_compilation']);if($compilation)$artist='Various Artists';if(!$artist||!$title||!in_array($format,['CD','LP'],true)) throw new RuntimeException('Artiest, titel en type zijn verplicht.');$tracks=trim($_POST['tracklist']??'');$trackArtists=normalizedTrackArtists($tracks,trim($_POST['track_artists']??''),$artist,$compilation);$cover=imageUpload('cover');$thumb=thumbnailForCover($cover); db()->prepare('INSERT INTO records(artist,title,format,barcode,tracklist,track_artists,release_year,duration_seconds,cover_path,cover_thumb_path,is_compilation,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$artist,$title,$format,trim($_POST['barcode']??''),$tracks,$trackArtists,(int)($_POST['release_year']??0)?:null,(int)($_POST['duration_seconds']??0)?:null,$cover,$thumb,$compilation?1:0,$_SESSION['user_id']]);flash('Toegevoegd aan je collectie.');redirect('?page=dashboard'); }
    } catch(Throwable $e) { flash($e->getMessage(),'error'); redirect('?page='.($form==='record'?'add':($form==='refresh_record'?'record&id='.(int)($_POST['id']??0):($form==='setup'?'setup':($form==='openai_settings'?'integrations':'login'))))); }
}

if ($count===0) layout('Eerste installatie','<section class="card auth"><h1>Maak je kluis</h1><p>Dit is een eenmalige stap. Kies een sterk wachtwoord; er is geen standaardaccount.</p><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input type="hidden" name="form" value="setup"><label>E-mailadres</label><input type="email" name="email" autocomplete="email" required><label>Wachtzin <span class="muted">(minimaal 12 tekens)</span></label><input type="password" name="password" minlength="12" autocomplete="new-password" required><div class="actions"><button>Account aanmaken</button></div></form></section>');
