$statement=db()->prepare('SELECT * FROM records WHERE user_id=? AND deleted_at IS NULL ORDER BY created_at DESC');$statement->execute([$_SESSION['user_id']]);$rows=$statement->fetchAll();$items='';foreach($rows as $r){$image=($r['cover_path']||$r['barcode'])?'<img class="cover" src="?action=image&amp;id='.$r['id'].'&amp;size=thumb" alt="">':'<div class="cover"></div>';$search=strtolower($r['artist'].' '.$r['title'].' '.$r['barcode']);$meta=($r['release_year']?:'—').' · '.playtime($r['duration_seconds']?(int)$r['duration_seconds']:null);$tagClass=$r['format']==='LP'?'tag tag-lp':'tag';$compilation=$r['is_compilation']?'<span class="tag tag-compilation">Verzamelalbum</span>':'';$items.='<article class="record" data-search="'.e($search).'" data-format="'.e($r['format']).'"><a href="?page=record&amp;id='.$r['id'].'">'.$image.'</a><div class="record-body"><div class="record-tags"><span class="'.$tagClass.'">'.e($r['format']).'</span>'.$compilation.'</div><div class="record-identity"><p><span>Artiest</span>'.e($r['artist']).'</p><p><span>Titel</span>'.e($r['title']).'</p></div><p>'.e((string)$meta).'</p></div></article>';}
layout('Collectie','<section class="hero"><h1>Je muziek, altijd bij de hand.</h1><p>Leg je cd’s en lp’s vast, inclusief hoes, tracklijst en barcode.</p><div class="actions"><a class="button" href="?page=add">+ Nieuwe uitgave</a><a class="button secondary" href="?page=scan">Barcode scannen</a><a class="button secondary" href="?page=scan&amp;mode=store">Scan in winkel</a></div></section><div class="toolbar"><strong id="collection-count">'.count($rows).' uitgave'.(count($rows)===1?'':'s').'</strong><div class="collection-filters"><select id="format-filter" aria-label="Filter op type"><option value="">Alle types</option><option value="CD">Alleen cd’s</option><option value="LP">Alleen lp’s</option></select><input id="filter" type="search" placeholder="Zoek artiest, titel of barcode" autocomplete="off"></div></div>'.($items?'<section class="collection collection-list">'.$items.'</section>':'<section class="card empty">Je collectie is nog leeg. <a href="?page=add">Voeg je eerste uitgave toe.</a></section>'));
